parameters.$filter:
@concat(
    'createdon ge ',
    '''',
    triggerBody()?['Text'],
    '''',
    ' and createdon lt ',
    '''',
    formatDateTime(
        addDays(
            triggerBody()?['Text_1'],
            1
        ),
        'yyyy-MM-ddT00:00:00Z'
    ),
    '''',

    if(
        equals(
            triggerBody()?['Text_2'],
            'All Statuses'
        ),
        '',
        concat(
            ' and dg_ticketstatus eq ',
            if(
                equals(triggerBody()?['Text_2'], 'New'),
                '121790000',
                if(
                    equals(triggerBody()?['Text_2'], 'Assigned'),
                    '121790001',
                    if(
                        equals(triggerBody()?['Text_2'], 'In Progress'),
                        '121790002',
                        if(
                            equals(triggerBody()?['Text_2'], 'Pending Further Action'),
                            '121790003',
                            if(
                                equals(triggerBody()?['Text_2'], 'Resolved'),
                                '121790004',
                                if(
                                    equals(triggerBody()?['Text_2'], 'Closed'),
                                    '121790005',
                                    ''
                                )
                            )
                        )
                    )
                )
            )
        )
    ),

    if(
        equals(
            triggerBody()?['Text_3'],
            'All Types'
        ),
        '',
        if(
            equals(
                triggerBody()?['Text_3'],
                'Peripheral Request'
            ),
            ' and dg_requesttype eq 121790000',
            if(
                equals(
                    triggerBody()?['Text_3'],
                    'System Access Request'
                ),
                ' and dg_requesttype eq 121790001',
                if(
                    equals(
                        triggerBody()?['Text_3'],
                        'Access Control Request'
                    ),
                    ' and dg_requesttype eq 121790002',
                    if(
                        equals(
                            triggerBody()?['Text_3'],
                            'Change Request'
                        ),
                        ' and dg_requesttype eq 121790003',
                        if(
                            equals(
                                triggerBody()?['Text_3'],
                                'Peripheral Incident'
                            ),
                            ' and dg_incident eq 121790000',
                            if(
                                equals(
                                    triggerBody()?['Text_3'],
                                    'Systems Access Incident'
                                ),
                                ' and dg_incident eq 121790001',
                                if(
                                    equals(
                                        triggerBody()?['Text_3'],
                                        'Access Control Incident'
                                    ),
                                    ' and dg_incident eq 121790002',
                                    if(
                                        equals(
                                            triggerBody()?['Text_3'],
                                            'Network/Internet Connectivity Incident'
                                        ),
                                        ' and dg_incident eq 121790003',
                                        ''
                                    )
                                )
                            )
                        )
                    )
                )
            )
        )
    )
)
